mapper.select:
select sp1.*,sp2.name
from tb_screen_ppd sp1
left join tb_screen_person sp2 on sp1.person_id=sp2.id
where sp2.screen_point=#{screenPoint}
and sp1.year=#{year}
and sp1.deleted=0
and sp2.deleted=0

    and sp1.screen_id like concat('%',#{screenId},'%')


    and sp1.injection=#{injection}

order by sp1.id desc

    limit #{pageNo},#{pageSize}

select ifnull(count(*),0)
from tb_screen_ppd sp1
left join tb_screen_person sp2 on sp1.person_id=sp2.id
where sp2.screen_point=#{screenPoint}
and sp1.year=#{year}
and sp1.deleted=0
and sp2.deleted=0

    and sp1.screen_id like concat('%',#{screenId},'%')


    and sp1.injection=#{injection}
